function luhnOk(digits) {
  let sum = 0;
  let alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (alt) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    alt = !alt;
  }
  return sum % 10 === 0;
}

function redact(text) {
  const counts = { email: 0, phone: 0, ssn: 0, card: 0, ipv4: 0 };
  let out = String(text || '');
  const swap = (pattern, label, key) => {
    out = out.replace(pattern, () => {
      counts[key] += 1;
      return '[' + label + '_' + counts[key] + ']';
    });
  };
  swap(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, 'EMAIL', 'email');
  swap(/\b\d{3}-\d{2}-\d{4}\b/g, 'SSN', 'ssn');
  swap(/\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g, 'IP', 'ipv4');
  swap(/(?:\+?\d{1,3}[\s.-]?)?(?:\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]\d{4}\b/g, 'PHONE', 'phone');
  out = out.replace(/\b(?:\d[ -]*?){13,19}\b/g, (match) => {
    const digits = match.replace(/\D/g, '');
    if (digits.length < 13 || digits.length > 19 || !luhnOk(digits)) return match;
    counts.card += 1;
    return '[CARD_' + counts.card + ']';
  });
  return { text: out, counts };
}

const results = [];
for (const item of $input.all()) {
  const raw = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;
  const original = String(raw.text || raw.body || raw.document || '');
  const task = String(raw.task || 'Summarize the document for an internal reader. Do not guess redacted values.');
  const redacted = redact(original.slice(0, 20000));
  results.push({
    json: {
      task,
      redactedText: redacted.text,
      redactionCounts: redacted.counts,
      originalLength: original.length,
    },
  });
}
return results;

