const draft = $input.first().json;
const modelText = typeof draft.text === 'string' ? draft.text : (typeof draft.output === 'string' ? draft.output : JSON.stringify(draft));
const patterns = [
  { name: 'email', re: /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i },
  { name: 'ssn', re: /\b\d{3}-\d{2}-\d{4}\b/ },
  { name: 'phone', re: /(?:\+?\d{1,3}[\s.-]?)?(?:\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]\d{4}\b/ },
  { name: 'ipv4', re: /\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/ },
];
const leaks = patterns.filter((pattern) => pattern.re.test(modelText)).map((pattern) => pattern.name);
const prepared = $('Redact PII').first().json;
if (leaks.length) {
  return [{
    json: {
      blocked: true,
      result: null,
      leaks,
      redactionCounts: prepared.redactionCounts,
      reason: 'The model output still matched a personal-data pattern, so the text was dropped.',
    },
  }];
}
return [{
  json: {
    blocked: false,
    result: modelText,
    leaks: [],
    redactionCounts: prepared.redactionCounts,
    originalLength: prepared.originalLength,
  },
}];
